// Generated Base64 Store Items & Empty Store Background for 100% instant offline/web rendering
import 'dart:convert';
import 'dart:typed_data';

class ItemImageData {
  static final Map<String, Uint8List> _cache = {};
  static Uint8List? _emptyStoreBgCache;
  static Uint8List? _closedStoreBgCache;
  static Uint8List? _bodegaBgCache;
  static Uint8List? _backRoomRefBgCache;
  static Uint8List? _garageBgCache;

  static Uint8List get garageBgBytes {
    return _garageBgCache ??= base64Decode(_garageBgBase64);
  }

  static Uint8List get backRoomRefBgBytes {
    return _backRoomRefBgCache ??= base64Decode(_backRoomRefBgBase64);
  }

  static Uint8List get bodegaBgBytes {
    return _bodegaBgCache ??= base64Decode(_bodegaBgBase64);
  }

  static Uint8List get closedStoreBgBytes {
    return _closedStoreBgCache ??= base64Decode(_closedStoreBgBase64);
  }

  static Uint8List get emptyStoreBgBytes {
    return _emptyStoreBgCache ??= base64Decode(_emptyStoreBgBase64);
  }

  static Uint8List? getBytes(String itemId) {
    if (_cache.containsKey(itemId)) return _cache[itemId];
    final b64 = _base64Map[itemId];
    if (b64 == null) return null;
    final bytes = base64Decode(b64);
    _cache[itemId] = bytes;
    return bytes;
  }

  static final Map<String, String> _base64Map = {
    'kape': '',
    'shampoo': '',
    'sabon': '',
    'chichirya': '',
    'candy': '',
    'itlog': '',
    'yosi': '',
    'bigas': '',
    'de_lata': '',
    'noodles': '',
    'softdrinks': '',
    'tubig': '',
  };

  static const String _emptyStoreBgBase64 = '';

  static const String _closedStoreBgBase64 = '';

  static const String _bodegaBgBase64 = '';

  static const String _backRoomRefBgBase64 = '';

  static const String _garageBgBase64 = '';
}
